"""Describe an upload from Content-Type header and initial bytes of data."""

from web_utils import parse_content_type, content_charset, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """Return a dict describing the upload:
    {
      "mime": lower-cased media type without parameters,
      "charset": lower-cased charset parameter or None,
      "image": "png", "jpeg", "gif" or None detected from data signature
    }
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()
    else:
        charset = None
    img = image_type(data)
    if img not in ("png", "jpeg", "gif"):
        img = None
    return {"mime": mime, "charset": charset, "image": img}

from version_compare import meets_minimum, latest_version


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version string from `versions` that is at least `minimum`.
    Return None if no version qualifies."""
    compatible = [v for v in versions if meets_minimum(v, minimum)]
    return latest_version(compatible)

from packaging.version import Version


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version from `versions` that is >= `minimum`, or None if none qualify."""
    min_ver = Version(minimum)
    best_version = None
    best_ver_obj = None
    for v in versions:
        ver_obj = Version(v)
        if ver_obj >= min_ver:
            if best_ver_obj is None or ver_obj > best_ver_obj:
                best_ver_obj = ver_obj
                best_version = v
    return best_version

import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently from synchronous code, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.
    Can be called repeatedly in the same process.
    """
    async def _run_all_with_timeout(coros, timeout):
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
        # Prepare results in input order
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                results.append(None)
        return results

    return run_sync(_run_all_with_timeout(coros, seconds))

import asyncio
from typing import Any, Coroutine, List, Optional


def run_with_deadline(coros: List[Coroutine[Any, Any, Any]], seconds: float) -> List[Optional[Any]]:
    """
    Run the given coroutines concurrently, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.

    Args:
        coros: List of coroutine objects to run.
        seconds: Timeout in seconds.

    Returns:
        List of results or None for timed-out coroutines.
    """
    async def _run_all_with_timeout(coros: List[Coroutine[Any, Any, Any]], timeout: float) -> List[Optional[Any]]:
        tasks = [asyncio.create_task(coro) for coro in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:
                # Ignore exceptions from cancelled tasks
                pass
        results = []
        for task in tasks:
            if task.done():
                try:
                    results.append(task.result())
                except Exception:
                    # If a task raised an exception, propagate it
                    raise
            else:
                results.append(None)
        return results

    return asyncio.run(_run_all_with_timeout(coros, seconds))
